# Run post-install commands
def "main post-install" [
    --dry-run (-n)
    --config (-c): string = "config.toml"
] {
    let platform = get-platform
    let cfg = open $config
    let post = if ("post_install" in ($cfg | columns)) { $cfg.post_install } else { null }

    if ($post == null) {
        print "No post-install commands defined."
        return
    }

    mut commands = []

    # Collect "all" platform commands
    if ("all" in ($post | columns)) {
        let all_cmds = $post.all
        for col in ($all_cmds | columns) {
            $commands = ($commands | append { name: $col, cmd: ($all_cmds | get $col) })
        }
    }

    # Collect platform-specific commands
    let platform_keys = match $platform {
        "macos" => ["unix" "macos"]
        "wsl" => ["unix" "wsl"]
        "linux" => ["unix" "linux"]
        _ => [$platform]
    }
    for platform_key in $platform_keys {
        if ($platform_key in ($post | columns)) {
            let plat_cmds = $post | get $platform_key
            for col in ($plat_cmds | columns) {
                $commands = ($commands | append { name: $col, cmd: ($plat_cmds | get $col) })
            }
        }
    }

    if ($commands | is-empty) {
        print "No post-install commands for this platform."
        return
    }

    for entry in $commands {
        if $dry_run {
            print $"  [DRY RUN] ($entry.name): ($entry.cmd)"
        } else {
            print $"  ($entry.name)... " --no-newline
            try {
                nu -c $entry.cmd
                print $"(ansi green)OK(ansi reset)"
            } catch {
                print $"(ansi yellow)SKIP(ansi reset)"
            }
        }
    }
}

# Show installation status
def "main status" [
    --personal (-p) 
    --config (-c): string = "config.toml"
] {
    let platform = get-platform
    let manager = get-manager $platform
    if ($manager == null) {
        print $"(ansi red)Error:(ansi reset) No package manager found"
        return
    }

    let cfg = open $config
    let sections = sections-for-platform $platform $personal

# env.nu — Nushell environment config
# Loaded before config.nu on every shell start

# --- Platform-specific PATH ---
if ($nu.os-info.name == "linux") {
    # Homebrew on Linux/WSL
    if ("/home/linuxbrew/.linuxbrew/bin" | path exists) {
        $env.PATH = ($env.PATH | prepend "/home/linuxbrew/.linuxbrew/bin")
    }
    # fnm path
    let fnm_path = $"($env.HOME)/.local/share/fnm"
    if ($fnm_path | path exists) {
        $env.PATH = ($env.PATH | prepend $fnm_path)
    }
} else if ($nu.os-info.name == "macos") {
    if ("/opt/homebrew/bin" | path exists) {
        $env.PATH = ($env.PATH | prepend "/opt/homebrew/bin")
    }
}

# --- Docker Desktop CLI (symlinks in ~/.docker/bin) ---
# zsh gets this via `export PATH="$HOME/.docker/bin:$PATH"` in ~/.zshrc,
# which nushell never sources — so ensure it here instead of relying on inheritance.
let docker_bin = ($env.HOME | path join ".docker" "bin")
if ($docker_bin | path exists) and ($docker_bin not-in $env.PATH) {
    $env.PATH = ($env.PATH | prepend $docker_bin)
}

# --- ~/.local/bin (uv tools, pdfpad) ---
let local_bin = ($env.HOME | path join ".local" "bin")
if ($local_bin | path exists) and ($local_bin not-in $env.PATH) {
    $env.PATH = ($env.PATH | prepend $local_bin)
}

# --- fnm (Node version manager) ---
# NB: `fnm env --json` does not include PATH (fnm 1.39+), so prepend this
# shell's multishell bin explicitly — this mirrors what `eval "$(fnm env)"`
# does for zsh. The multishell path is stable per shell instance, so later
# `fnm use <version>` switches keep working without further PATH changes.
try {
    fnm env --json | from json | load-env
    if "FNM_MULTISHELL_PATH" in $env {
        let multishell_bin = ($env.FNM_MULTISHELL_PATH | path join "bin")
        if ($multishell_bin not-in $env.PATH) {
            $env.PATH = ($env.PATH | prepend $multishell_bin)
        }
    }
}

